CREATE TABLE public.civic_directory_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),person_id uuid NOT NULL REFERENCES public.civic_people(id),kind text NOT NULL DEFAULT 'portrait',source_url text NOT NULL,image_url text,license_url text,credit text,identity_evidence text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,last_error text,storage_path text,sha256 text,contact_phone text,contact_email text,created_by uuid NOT NULL,reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),next_attempt_at timestamptz NOT NULL DEFAULT now(),UNIQUE(person_id,kind,source_url));
GRANT SELECT,INSERT,UPDATE ON public.civic_directory_jobs TO authenticated; GRANT ALL ON public.civic_directory_jobs TO service_role;
ALTER TABLE public.civic_directory_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY directory_admin_jobs ON public.civic_directory_jobs FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') AND public.account_active(auth.uid())) WITH CHECK(public.has_role(auth.uid(),'admin') AND public.account_active(auth.uid()));
CREATE TRIGGER directory_jobs_audit AFTER INSERT OR UPDATE ON public.civic_directory_jobs FOR EACH ROW EXECUTE FUNCTION public.audit_civic_directory();
COMMENT ON TABLE public.civic_directory_jobs IS 'Admin-created identity/source-evidence candidates. Acquisition does not imply verification; explicit review required. Bounded retry and progress survive browser/worker restarts.';